package cn.haiduo;
import cn.haiduo.orders.CsvOrders;import cn.haiduo.inventory.InventoryService;
import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.mock.web.MockHttpSession;import org.springframework.web.server.ResponseStatusException;
import org.testcontainers.postgresql.PostgreSQLContainer;import org.flywaydb.core.Flyway;
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="RUN_DATABASE_TESTS",matches="true")
class CsvBatchContainerTest {
 static PostgreSQLContainer pg;static JdbcTemplate db;static TransactionTemplate tx;UUID tenant,sku;final UUID warehouse=UUID.fromString("00000000-0000-0000-0000-000000000001");CsvOrders csv;CsvBatchService batches;InventoryService inventory;InventoryCorrections approvals;MockHttpSession session;
 static final String HEADER="store,order_no,sku,quantity,net,currency,rate\n";
 @BeforeAll static void start(){pg=new PostgreSQLContainer("postgres:17.6").withDatabaseName("haiduo").withUsername("haiduo").withPassword("test-password");pg.start();var ds=new DriverManagerDataSource(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());Flyway.configure().dataSource(ds).load().migrate();db=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));}
 @AfterAll static void stop(){if(pg!=null)pg.stop();}
 @BeforeEach void setup(){tenant=UUID.randomUUID();sku=UUID.randomUUID();db.update("insert into tenant values(?,'csv-batch')",tenant);db.update("insert into warehouse values(?,?,'default')",tenant,warehouse);db.update("insert into store values(?,?,'mock','MOCK','MOCK')",UUID.randomUUID(),tenant);db.update("insert into product(id,tenant_id,name) values(?,?,'test')",sku,tenant);db.update("insert into sku(id,tenant_id,code,name,cost,product_id) values(?,?,'A','test',200,?)",sku,tenant,sku);db.update("insert into inventory(tenant_id,sku_id,on_hand,reserved,warehouse_id) values(?,?,100,0,?)",tenant,sku,warehouse);for(String user:List.of("csv-requester","csv-reviewer")){db.update("insert into app_user(username,password_hash) values(?,'unused') on conflict do nothing",user);db.update("insert into membership values(?,?,'OPERATIONS')",user,tenant);db.update("insert into member_grade values(?,?,?)",tenant,user,user.equals("csv-requester")?1:3);}csv=new CsvOrders(db);batches=new CsvBatchService(db);inventory=new InventoryService(db);approvals=new InventoryCorrections(db,new OperationsController(db,new SessionController(db),inventory),inventory);session=new MockHttpSession();session.setAttribute("activeTenant",tenant.toString());}
 String text(String... numbers){return HEADER+String.join("\n",Arrays.stream(numbers).map(n->"mock,"+n+",A,1,100.00,USD,7.2").toList());}
 @SuppressWarnings("unchecked") Map<String,Object> preview(String text){return (Map<String,Object>)csv.preview(tenant,warehouse,text);}
 @SuppressWarnings("unchecked") Map<String,Object> commit(String text,UUID key,String digest){return (Map<String,Object>)tx.execute(s->csv.importOrders(tenant,warehouse,text,"csv-requester",key,digest));}
 UUID batch(Map<String,Object> result){return (UUID)result.get("batchId");}
 UUID request(UUID batch){return (UUID)((Map<?,?>)tx.execute(s->approvals.submit(new InventoryCorrections.Request("CSV_ROLLBACK",batch,"wrong import",UUID.randomUUID()),()->"csv-requester",session))).get("id");}
 void approve(UUID id){tx.executeWithoutResult(s->approvals.decide(id,new InventoryCorrections.Decision("approve","checked"),()->"csv-reviewer",session));}
 int count(String table){return db.queryForObject("select count(*) from "+table+" where tenant_id=?",Integer.class,tenant);}
 @Test void previewIsReadOnlyAndAggregatesLineErrors(){assertThrows(IllegalStateException.class,()->csv.importOrders(tenant,warehouse,text("NO-TX"),"csv-requester"));var result=preview(HEADER+"mock,BAD,FOREIGN,1,100,USD,7.2\nmock,BAD2,A,0,100,USD,7.2");assertEquals(false,result.get("canImport"));assertEquals(2,((List<?>)result.get("errors")).size());assertEquals(0,count("sales_order"));assertEquals(0,count("audit_log"));assertEquals(0,count("outbox_event"));assertThrows(ResponseStatusException.class,()->commit(HEADER+"mock,GOOD,A,1,100,USD,7.2\nmock,BAD,A,0,100,USD,7.2",UUID.randomUUID(),null));assertEquals(0,count("sales_order"));assertEquals(0,count("csv_import_batch"));}
 @Test void costVersionChangeInvalidatesPreviewWithoutPartialWrite(){String text=text("ONE");String digest=(String)preview(text).get("digest");db.update("update sku set cost=220,version=version+1 where id=?",sku);assertEquals(409,assertThrows(ResponseStatusException.class,()->commit(text,UUID.randomUUID(),digest)).getStatusCode().value());assertEquals(0,count("sales_order"));assertEquals(0,count("csv_import_batch"));}
 @Test void duplicateOrdersNeverBelongToNewRollbackBatch(){UUID first=batch(commit(text("OLD"),UUID.randomUUID(),null));var view=preview(text("OLD","NEW"));assertEquals(1,view.get("imported"));assertEquals(1,view.get("duplicates"));UUID second=batch(commit(text("OLD","NEW"),UUID.randomUUID(),(String)view.get("digest")));assertEquals(1,((List<?>)batches.detail(tenant,second).get("orders")).size());assertThrows(IllegalStateException.class,()->batches.rollback(tenant,second,"csv-reviewer"));UUID approval=request(second);for(int i=0;i<10;i++)approve(approval);assertEquals("NEW",db.queryForObject("select status from sales_order where tenant_id=? and external_id='OLD'",String.class,tenant));assertEquals(true,db.queryForObject("select import_voided from sales_order where tenant_id=? and external_id='NEW'",Boolean.class,tenant));assertEquals("ACTIVE",((Map<?,?>)batches.detail(tenant,first).get("batch")).get("status"));assertEquals(2,count("sales_order"));assertEquals(2,count("order_item"));}
 @Test void laterFeePreventsWholeBatchRollback(){UUID id=batch(commit(text("ONE","TWO"),UUID.randomUUID(),null));UUID approval=request(id);UUID order=db.queryForObject("select id from sales_order where tenant_id=? and external_id='ONE'",UUID.class,tenant);db.update("insert into order_fee(tenant_id,order_id,kind,amount_cny,original_amount,currency,exchange_rate,rate_source,effective_at) values(?,?,'FREIGHT',0,0,'CNY',1,'test',now())",tenant,order);approve(approval);assertEquals("STALE",db.queryForObject("select status from inventory_correction where id=?",String.class,approval));assertEquals(0,db.queryForObject("select count(*) from sales_order where tenant_id=? and import_voided",Integer.class,tenant));assertEquals("ACTIVE",((Map<?,?>)batches.detail(tenant,id).get("batch")).get("status"));}
 @Test void importRetryIsIdempotentAndRollbackKeepsOrderNumberReserved(){String text=text("ONE");UUID key=UUID.randomUUID();String digest=(String)preview(text).get("digest");var ids=java.util.stream.IntStream.range(0,10).parallel().mapToObj(i->batch(commit(text,key,digest))).distinct().toList();assertEquals(1,ids.size());assertEquals(1,count("sales_order"));assertEquals(1,count("csv_import_batch"));assertEquals(409,assertThrows(ResponseStatusException.class,()->commit(text("OTHER"),key,null)).getStatusCode().value());approve(request(ids.getFirst()));var replay=commit(text,UUID.randomUUID(),null);assertEquals(0,replay.get("imported"));assertEquals(1,replay.get("duplicates"));assertEquals(1,count("sales_order"));assertEquals(false,batches.detail(tenant,batch(replay)).get("canRollback"));}
 @Test void reserveHistoryBlocksAndCrossTenantBatchIsHidden(){UUID id=batch(commit(text("ONE"),UUID.randomUUID(),null));UUID order=db.queryForObject("select id from sales_order where tenant_id=?",UUID.class,tenant);tx.executeWithoutResult(s->{inventory.transition(tenant,order,"reserve");inventory.release(tenant,order,1);});assertEquals(false,batches.detail(tenant,id).get("canRollback"));assertEquals(409,assertThrows(ResponseStatusException.class,()->request(id)).getStatusCode().value());UUID foreign=UUID.randomUUID();db.update("insert into tenant values(?,'foreign')",foreign);db.update("insert into membership values('csv-requester',?,'OPERATIONS')",foreign);session.setAttribute("activeTenant",foreign.toString());assertEquals(404,assertThrows(ResponseStatusException.class,()->request(id)).getStatusCode().value());}
 @Test void platformSyncCannotReviveVoidedCsvOrder(){UUID id=batch(commit(text("ONE"),UUID.randomUUID(),null));approve(request(id));UUID store=db.queryForObject("select id from store where tenant_id=?",UUID.class,tenant);var update=new cn.haiduo.platform.PlatformConnector.Order("ONE",java.time.Instant.now(),"USD",new java.math.BigDecimal("999"),"PAID","NONE",false,"FULFILLED",List.of(new cn.haiduo.platform.PlatformConnector.Item("A","A",1)));tx.executeWithoutResult(s->new SyncProcessor(db,null,inventory).upsert(tenant,store,"mock",warehouse,true,update));assertEquals("CANCELLED",db.queryForObject("select status from sales_order where tenant_id=?",String.class,tenant));assertEquals("100.0000",db.queryForObject("select net::text from sales_order where tenant_id=?",String.class,tenant));assertEquals("UNKNOWN",db.queryForObject("select payment_status from sales_order where tenant_id=?",String.class,tenant));}
}
